module TopModule (
    input  clk,
    input  reset,
    input  data,
    output [3:0] count,
    output counting,
    output done,
    input  ack
);
    localparam S0 = 3'd0, S1 = 3'd1, S2 = 3'd2, S3 = 3'd3, SHIFT = 3'd4, COUNT = 3'd5, DONE = 3'd6;

    reg [2:0] state;
    reg [1:0] sc;
    reg [3:0] rem;
    reg [9:0] cyc;

    always @(posedge clk) begin
        if (reset) begin
            state <= S0;
            sc    <= 2'd0;
            rem   <= 4'd0;
            cyc   <= 10'd0;
        end else begin
            case (state)
                S0:    state <= data ? S1 : S0;
                S1:    state <= data ? S2 : S0;
                S2:    state <= data ? S2 : S3;
                S3:    state <= data ? SHIFT : S0;
                SHIFT: begin
                    rem <= {rem[2:0], data};
                    sc  <= sc + 2'd1;
                    if (sc == 2'd3) state <= COUNT;
                end
                COUNT: begin
                    if (cyc == 10'd999) begin
                        cyc <= 10'd0;
                        if (rem == 4'd0) state <= DONE;
                        else rem <= rem - 4'd1;
                    end else begin
                        cyc <= cyc + 10'd1;
                    end
                end
                DONE:  if (ack) state <= S0;
                default: state <= S0;
            endcase
        end
    end

    assign count    = rem;
    assign counting = (state == COUNT);
    assign done     = (state == DONE);

endmodule

module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    input  logic done_counting,
    input  logic ack,
    output logic shift_ena,
    output logic counting,
    output logic done
);

    typedef enum logic [3:0] {
        S, S1, S11, S110, B0, B1, B2, B3, COUNT, DONE_S
    } state_t;

    state_t state, next_state;

    always_ff @(posedge clk) begin
        if (reset) state <= S;
        else       state <= next_state;
    end

    always_comb begin
        next_state = state;
        case (state)
            S:       next_state = data ? S1 : S;
            S1:      next_state = data ? S11 : S;
            S11:     next_state = data ? S11 : S110;
            S110:    next_state = data ? B0 : S;
            B0:      next_state = B1;
            B1:      next_state = B2;
            B2:      next_state = B3;
            B3:      next_state = COUNT;
            COUNT:   next_state = done_counting ? DONE_S : COUNT;
            DONE_S:  next_state = ack ? S : DONE_S;
            default: next_state = S;
        endcase
    end

    assign shift_ena = (state == B0) || (state == B1) || (state == B2) || (state == B3);
    assign counting  = (state == COUNT);
    assign done      = (state == DONE_S);

endmodule

