module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    input  logic dig,
    output logic walk_left,
    output logic walk_right,
    output logic aaah,
    output logic digging
);

    typedef enum logic [2:0] {
        WL, WR, FL, FR, DL, DR, SPLAT
    } state_t;

    state_t state, next;
    logic [4:0] fall_cnt;

    always_comb begin
        next = state;
        case (state)
            WL: begin
                if (!ground)          next = FL;
                else if (dig)         next = DL;
                else if (bump_left)   next = WR;
            end
            WR: begin
                if (!ground)          next = FR;
                else if (dig)         next = DR;
                else if (bump_right)  next = WL;
            end
            FL: if (ground) next = (fall_cnt > 20) ? SPLAT : WL;
            FR: if (ground) next = (fall_cnt > 20) ? SPLAT : WR;
            DL: if (!ground) next = FL;
            DR: if (!ground) next = FR;
            default: next = SPLAT;
        endcase
    end

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state    <= WL;
            fall_cnt <= '0;
        end else begin
            state <= next;
            if (state == FL || state == FR) begin
                if (fall_cnt < 21) fall_cnt <= fall_cnt + 5'd1;
            end else begin
                fall_cnt <= '0;
            end
        end
    end

    assign walk_left  = (state == WL);
    assign walk_right = (state == WR);
    assign aaah       = (state == FL) || (state == FR);
    assign digging    = (state == DL) || (state == DR);

endmodule

