module TopModule (
    input clk,
    input resetn,
    input [2:0] r,
    output [2:0] g
);

    localparam [1:0] A = 2'd0,
                     B = 2'd1,
                     C = 2'd2,
                     D = 2'd3;

    reg [1:0] state;
    reg [1:0] next_state;

    always @(*) begin
        case (state)
            A: begin
                if (r[0])
                    next_state = B;
                else if (r[1])
                    next_state = C;
                else if (r[2])
                    next_state = D;
                else
                    next_state = A;
            end
            B: next_state = r[0] ? B : A;
            C: next_state = r[1] ? C : A;
            D: next_state = r[2] ? D : A;
            default: next_state = A;
        endcase
    end

    always @(posedge clk) begin
        if (!resetn)
            state <= A;
        else
            state <= next_state;
    end

    assign g[0] = (state == B);
    assign g[1] = (state == C);
    assign g[2] = (state == D);

endmodule

module TopModule (
    input  logic       clk,
    input  logic       areset,
    input  logic       predict_valid,
    input  logic [6:0] predict_pc,
    output logic       predict_taken,
    output logic [6:0] predict_history,
    input  logic       train_valid,
    input  logic       train_taken,
    input  logic       train_mispredicted,
    input  logic [6:0] train_history,
    input  logic [6:0] train_pc
);
    logic [6:0] ghr;
    logic [1:0] pht [0:127];

    wire [6:0] predict_index = predict_pc ^ ghr;
    wire [6:0] train_index   = train_pc ^ train_history;

    assign predict_taken   = pht[predict_index][1];
    assign predict_history = ghr;

    integer i;
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'd0;
            for (i = 0; i < 128; i = i + 1)
                pht[i] <= 2'b01;
        end else begin
            if (train_valid) begin
                if (train_taken && pht[train_index] != 2'b11)
                    pht[train_index] <= pht[train_index] + 2'b01;
                else if (!train_taken && pht[train_index] != 2'b00)
                    pht[train_index] <= pht[train_index] - 2'b01;
            end

            if (train_valid && train_mispredicted)
                ghr <= {train_history[5:0], train_taken};
            else if (predict_valid)
                ghr <= {ghr[5:0], predict_taken};
        end
    end
endmodule

module TopModule (
  input  logic clk,
  input  logic reset,
  input  logic s,
  input  logic w,
  output logic z
);

  typedef enum logic [2:0] {A, B, C0, C1, D0, D1, D2, Z} state_t;

  state_t state, next_state;

  always_comb begin
    case (state)
      A:       next_state = s ? B : A;
      B:       next_state = w ? C1 : C0;
      C0:      next_state = w ? D1 : D0;
      C1:      next_state = w ? D2 : D1;
      D0:      next_state = B;
      D1:      next_state = w ? Z : B;
      D2:      next_state = w ? B : Z;
      Z:       next_state = w ? C1 : C0;
      default: next_state = A;
    endcase
  end

  always_ff @(posedge clk) begin
    if (reset)
      state <= A;
    else
      state <= next_state;
  end

  assign z = (state == Z);

endmodule

