module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    localparam LEFT = 3'd0, RIGHT = 3'd1, FALL_L = 3'd2, FALL_R = 3'd3, DIG_L = 3'd4, DIG_R = 3'd5;

    reg [2:0] state, next;

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= LEFT;
        else
            state <= next;
    end

    always @(*) begin
        case (state)
            LEFT:    next = !ground ? FALL_L : dig ? DIG_L : bump_left  ? RIGHT  : LEFT;
            RIGHT:   next = !ground ? FALL_R : dig ? DIG_R : bump_right ? LEFT   : RIGHT;
            FALL_L:  next = ground ? LEFT : FALL_L;
            FALL_R:  next = ground ? RIGHT : FALL_R;
            DIG_L:   next = !ground ? FALL_L : DIG_L;
            DIG_R:   next = !ground ? FALL_R : DIG_R;
            default: next = LEFT;
        endcase
    end

    assign walk_left  = (state == LEFT);
    assign walk_right = (state == RIGHT);
    assign aaah       = (state == FALL_L) || (state == FALL_R);
    assign digging    = (state == DIG_L) || (state == DIG_R);

endmodule

module TopModule (
    input  logic clk,
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);
    localparam logic [3:0] S_A  = 4'd0;
    localparam logic [3:0] S_B  = 4'd1;
    localparam logic [3:0] S_C  = 4'd2;
    localparam logic [3:0] S_D  = 4'd3;
    localparam logic [3:0] S_E  = 4'd4;
    localparam logic [3:0] S_F  = 4'd5;
    localparam logic [3:0] S_G1 = 4'd6;
    localparam logic [3:0] S_G0 = 4'd7;
    localparam logic [3:0] S_H  = 4'd8;

    logic [3:0] state, next;

    always_ff @(posedge clk) begin
        if (!resetn) state <= S_A;
        else         state <= next;
    end

    always_comb begin
        case (state)
            S_A:     next = S_B;
            S_B:     next = S_C;
            S_C:     next = x ? S_D : S_C;
            S_D:     next = x ? S_D : S_E;
            S_E:     next = x ? S_F : S_C;
            S_F:     next = y ? S_H : S_G1;
            S_G1:    next = y ? S_H : S_G0;
            S_G0:    next = S_G0;
            S_H:     next = S_H;
            default: next = S_A;
        endcase
    end

    assign f = (state == S_B);
    assign g = (state == S_F) || (state == S_G1) || (state == S_H);
endmodule

