module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    output logic walk_left,
    output logic walk_right,
    output logic aaah
);

    typedef enum logic [1:0] {
        WALK_LEFT  = 2'd0,
        WALK_RIGHT = 2'd1,
        FALL_LEFT  = 2'd2,
        FALL_RIGHT = 2'd3
    } state_t;

    state_t state, next_state;

    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            state <= WALK_LEFT;
        else
            state <= next_state;
    end

    always_comb begin
        case (state)
            WALK_LEFT:  next_state = !ground ? FALL_LEFT  : (bump_left  ? WALK_RIGHT : WALK_LEFT);
            WALK_RIGHT: next_state = !ground ? FALL_RIGHT : (bump_right ? WALK_LEFT  : WALK_RIGHT);
            FALL_LEFT:  next_state = ground ? WALK_LEFT  : FALL_LEFT;
            FALL_RIGHT: next_state = ground ? WALK_RIGHT : FALL_RIGHT;
            default:    next_state = WALK_LEFT;
        endcase
    end

    assign walk_left  = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign aaah       = (state == FALL_LEFT) || (state == FALL_RIGHT);

endmodule

