    generate
        for (r = 0; r < 16; r = r + 1) begin : g_row
            for (c = 0; c < 16; c = c + 1) begin : g_col
                localparam integer UP = (r + 15) % 16;
                localparam integer DN = (r + 1) % 16;
                localparam integer LT = (c + 15) % 16;
                localparam integer RT = (c + 1) % 16;
