                             + q[r*16+LT]                + q[r*16+RT]
                             + q[DN*16+LT] + q[DN*16+c] + q[DN*16+RT];
                assign nxt[r*16+c] = (n == 4'd3) | (q[r*16+c] & (n == 4'd2));
            end
        end
    endgenerate

    always_ff @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= nxt;
    end
