module TopModule (
    input clk,
    input areset,
    input train_valid,
    input train_taken,
    output [1:0] state
);
    reg [1:0] cnt;
    assign state = cnt;

    always @(posedge clk or posedge areset) begin
        if (areset)
            cnt <= 2'b01;
        else if (train_valid) begin
            if (train_taken && cnt != 2'b11)
                cnt <= cnt + 2'b01;
            else if (!train_taken && cnt != 2'b00)
                cnt <= cnt - 2'b01;
        end
    end
endmodule

module TopModule (
