    output [31:0] predict_history
);
    reg [31:0] history;

    assign predict_history = history;

    always @(posedge clk or posedge areset) begin
        if (areset)
            history <= 32'd0;
        else if (train_mispredicted)
            history <= {train_history[30:0], train_taken};
        else if (predict_valid)
            history <= {history[30:0], predict_taken};
    end
endmodule

module TopModule (
  input  wire        clk,
  input  wire        load,
  input  wire        ena,
  input  wire [1:0]  amount,
  input  wire [63:0] data,
  output reg  [63:0] q
);

  always @(posedge clk) begin
    if (load)
      q <= data;
    else if (ena) begin
      case (amount)
        2'b00: q <= {q[62:0], 1'b0};
        2'b01: q <= {q[55:0], 8'b0};
        2'b10: q <= {q[63], q[63:1]};
        2'b11: q <= {{8{q[63]}}, q[63:8]};
      endcase
    end
  end

endmodule

module TopModule (
  input  clk,
  input  a,
  input  b,
  output q,
  output state
);
  reg state_r;
  always @(posedge clk)
    state_r <= (a & b) | (a & state_r) | (b & state_r);
  assign state = state_r;
  assign q = a ^ b ^ state_r;
endmodule

module TopModule (
    input  logic clk,
