module TopModule (
    input  logic       clk,
    input  logic       reset,
    input  logic       ena,
    output logic       pm,
    output logic [7:0] hh,
    output logic [7:0] mm,
    output logic [7:0] ss
);

    always_ff @(posedge clk) begin
        if (reset) begin
            hh <= 8'h12;
            mm <= 8'h00;
            ss <= 8'h00;
            pm <= 1'b0;
        end else if (ena) begin
            if (ss == 8'h59) begin
                ss <= 8'h00;
                if (mm == 8'h59) begin
                    mm <= 8'h00;
                    if (hh == 8'h12)
                        hh <= 8'h01;
                    else if (hh == 8'h11) begin
                        hh <= 8'h12;
                        pm <= ~pm;
                    end
                    else if (hh[3:0] == 4'h9)
                        hh <= 8'h10;
                    else
                        hh <= hh + 8'h01;
                end else begin
                    mm <= (mm[3:0] == 4'h9) ? {mm[7:4] + 4'd1, 4'h0} : mm + 8'h01;
                end
            end else begin
                ss <= (ss[3:0] == 4'h9) ? {ss[7:4] + 4'd1, 4'h0} : ss + 8'h01;
            end
        end
    end

endmodule

