module TopModule (
    input clk,
    input reset,
    input [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);
    localparam [2:0] Z0 = 3'd0, Z1U = 3'd1, Z1D = 3'd2, Z2U = 3'd3, Z2D = 3'd4, Z3 = 3'd5;

    reg [2:0] state, next;
    reg [1:0] cz;
    wire [1:0] lvl = s[2] ? 2'd3 : s[1] ? 2'd2 : s[0] ? 2'd1 : 2'd0;

    always @(*) begin
        case (state)
            Z0:      cz = 2'd0;
            Z1U, Z1D: cz = 2'd1;
            Z2U, Z2D: cz = 2'd2;
            default: cz = 2'd3;
        endcase
    end

    always @(*) begin
        if (lvl == cz)
            next = state;
        else if (lvl > cz) begin
            case (lvl)
                2'd0:    next = Z0;
                2'd1:    next = Z1U;
                2'd2:    next = Z2U;
                default: next = Z3;
            endcase
        end else begin
            case (lvl)
                2'd0:    next = Z0;
                2'd1:    next = Z1D;
                default: next = Z2D;
            endcase
        end
    end

    always @(posedge clk) begin
        if (reset)
            state <= Z0;
        else
            state <= next;
    end

    assign fr2 = (state == Z0);
    assign fr1 = (state == Z0) | (state == Z1U) | (state == Z1D);
    assign fr0 = (state != Z3);
    assign dfr = (state == Z0) | (state == Z1U) | (state == Z2U);

endmodule

